using static StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer.Constructor;

internal sealed class NativeMixedImageConstructionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/Constructor/NativeMixedImageConstruction.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Expression naming and unrestricted mixed native soundness",
        H("Original expressions and their named equations"), Blocks(
            Paragraph(Text("Source is the algebra of finite ordered Boolean trees. Pairing is its actual constructor, and rho is the interpreted native substitution. MixedExpr uses fixed ground trees, fixed natural powers of original variables, and pairing. A positive presentation is a finite list of pairs of these expressions. The list may be empty or contain repetitions. X retains every original variable, including unused variables; X may be Fin d, also when d is zero. No tree size or depth bound is imposed.")),
            Def("Name", "Disjoint input and auxiliary namespaces", "Name X is X plus MixedExpr X. Inputs are injected on the left and expression names on the right. Every repeated use of an expression has the same auxiliary name. This namespace itself is not finite: the finite lowering emits only the definitions needed by the supplied finite expressions. The finite presentation below restricts this namespace to the names read by the lowering and all declared inputs."),
            Def("root", "Name an original expression", "root injects an expression into the auxiliary namespace without changing its variables or ground parameters."),
            Def("groundDefinitions", "Expand ground parameters into finite native syntax", "A Boolean leaf has its primitive rank zero or one. A pair recursively includes both ground definitions and the pairing equation for their roots. This operation terminates by recursion on the supplied finite ground tree."),
            Def("definitions", "Lower every expression constructor", "A residual occurrence rho to power a of x becomes a shift from the original input name x to its expression root. A pair includes the definitions of its two children and an ordinary native pairing equation between their roots. Repeated definitions are retained."),
            Def("flatten", "Retain all positive equalities", "For each original pair of expressions, flatten concatenates both lists of definitions and an equality between the two expression roots. This is a concrete terminating function on the original syntax. It does not assume that the original positive equations already hold."),
            Def("extend", "Evaluate every named subexpression at the same source assignment", "extend keeps the input assignment on the left and evaluates the named expression on the right. No new choice of original source is made."),
            Thm("flatten_exact", "Exact lowering at the original assignment", "All original positive expression equalities hold at v if and only if every emitted named equation holds at extend v. For the forward direction, ground recursion verifies both primitive leaves and actual native pairs; expression recursion verifies each fixed power and each ordered pair. The reverse direction reads the emitted root equality for every supplied comparison. Unused input values remain those of v."),
            Thm("expression_branch_exact", "Finite canonical branches from original expression syntax", "The original expression equalities hold exactly when one member of branches(flatten E) holds on the actual canonical encodings of extend v. The concrete lowering theorem supplies the native named equations. The existing exact constructor-case theorem then chooses ordinary or collapse cases from those same actual values. This finite branch list does not enumerate scalar ranks or native sources, and still retains code equations rather than unrestricted image charts."),
            Thm("flatten_expansion_sound", "Expand arbitrary ambient branch solutions", "For any selected branch of flatten E, let u assign arbitrary finite ambient codes to names and satisfy that branch's code equations. Then expanding u on the original input names satisfies every original expression equality. Induction through the definitions identifies each expanded auxiliary value with evaluation of its original expression. Existing branch soundness supplies interpreted shifts, ordinary pairs, and the primitive collapse recurrence. Normality and injectivity of expansion are not premises. In particular an ordinary pair of consecutive primitive ranks may collapse after filling without invalidating its native pairing equation."),
            Def("equationNames", "Names read by one native equation", "List every input name of the equation, including its output. Repeated names are retained."),
            Def("nameSupport", "Finite support with the entire original tuple", "For d original inputs, concatenate every inl(i), i in Fin d, with all names read by flatten E, and deduplicate this finite list. Auxiliary expressions are identified by their actual syntax. No input is removed when it is absent from the equations."),
            Def("FiniteName", "The actual finite carrier", "FiniteName E is the subtype of Name(Fin d) belonging to nameSupport E. It contains all declared inputs and every auxiliary name used by a lowered equation."),
            Def("inputName", "Embed every original component", "inputName E i is the original input name in the finite carrier. Its underlying name is inl(i), so distinct original components remain distinct, including unused components."),
            Def("namePresentation", "Present the actual finite carrier to the unifier", "Use the deduplicated support list's explicit equivalence with its finite index interval and transport the existing finPresentation. This constructs the code and inverse decoder from the actual supplied finite syntax, without a default element or an assumed presentation of an infinite namespace."),
            Def("finiteEquations", "Reindex every lowered equation", "Each name in an equation of flatten E has a proof of support membership. Reindex that equation by the corresponding subtype elements, retaining the original list order and all repeated equations."),
            Def("finiteExtend", "Restrict the same actual named assignment", "finiteExtend E v reads extend v at the underlying supported name. In particular its value at inputName E i is v(i). Exact finite lowering and the existing native branch reduction supply a successful total MGU and its factorization at every supported name."),
            Paragraph(Text("Finite scalar guards and native templates.")), 
            Def("Scalar", "Affine natural rank atoms", "A scalar is a fixed natural constant, or n(i)+a for a natural parameter n(i) and a fixed natural offset a. Thus its integer interpretation is affine, with coefficient zero or one."),
            Def("Scalar.value", "Read a scalar parameter", "Scalar.value evaluates the constant or the parameter with its fixed offset in the natural numbers."),
            Def("Pattern", "Finite mixed ambient syntax", "A pattern is an explicit scalar leaf, a residual native block of sort i with a fixed natural offset a, or a pair of patterns. Different residual sorts receive independently supplied native values. Equal values across different sorts are permitted."),
            Def("Decoration", "Decorate exactly the actual shape leaves", "Decoration k m s is defined recursively on the supplied free-shape term s. An explicit primitive leaf carries a Scalar k. A residual leaf carries an element of Fin m and a fixed natural offset. A pair carries the decorations of its two children. Empty scalar or native dimensions therefore require no nonexistent selector when the corresponding leaves are absent."),
            Def("assemble", "Construct every named mixed pattern", "assemble traverses the actual free-shape term with its dependent decoration: explicit leaves become scalar patterns, residual occurrences become shifted native blocks, and binary nodes become pairs. A named family s and decorations d thus give the concrete pattern of every original and auxiliary name. Shared names reuse the same supplied term and decoration."),
            Def("Pattern.code", "Assemble ambient codes before expansion", "Scalar leaves become primitive codes; a residual block becomes shiftCode a (encode (z i)); pairs become raw ambient pairs. Pair assembly uses no smart normalization and adds no normality test."),
            Def("Pattern.template", "Return the established native mixed syntax", "A constant scalar becomes a fixed ground tree; a parameter scalar becomes the ranked residual rho to power a of T(n i); a block becomes rho to power a of z i; pairs remain actual native pairs. These are RankedExpr templates, using the existing rankedEval interpretation. Structural recursion proves that expanding Pattern.code is exactly rankedEval of this template."),
            Def("Guard", "A finite conjunction of affine integer equalities", "Guard is a list of pairs of scalar atoms. It has no native parameter fields."),
            Def("Guard.Holds", "The arithmetic domain", "Each scalar pair is required to have equal integer values. Its arguments range over all natural scalar tuples. No positivity, shape, disequality, source bound, or normality predicate on residual native values occurs in this guard."),
            Def("compare", "Extract scalar equalities from matching decorated syntax", "Two scalar leaves emit their affine equality. Two blocks succeed exactly when their residual sort and fixed offset agree syntactically, emitting no arithmetic condition. Two pairs recursively compare corresponding children and concatenate their guards. All other constructor combinations fail. Success is a sufficient symbolic comparison; no completeness of this procedure over arbitrary native equalities is asserted. In particular accidental equal native parameters are allowed, while the procedure need not recognize every equality caused by them."),
            Def("Scalar.shift", "Translate explicit ranks", "A fixed natural shift adds its offset to constants and parameter offsets."),
            Def("Pattern.shift", "Translate every ambient leaf", "Translation recursively shifts explicit scalar leaves and adds the supplied shift to every residual block offset. Pair structure is preserved. Its assembled code equals shiftCode of the unshifted assembled code."),
            Def("branchComparisons", "Extract every selected branch comparison", "Primitive equations compare the assigned output pattern with their fixed scalar. Shift equations compare the output with syntactic translation of the input; ordinary equations compare it with a raw pair; equalities compare their two named patterns. A collapse uses a supplied scalar atom c(b) and emits all three equations: left rank value(c(b))+1, right rank value(c(b)), and output rank value(c(b))+2. The same scalar is shared in those three comparisons."),
            Def("collect", "Combine a finite comparison family", "collect recursively runs compare on every pattern pair and concatenates the resulting scalar guards. Failure discards the attempted decorated syntax. Success proves all ambient comparisons for every native filling satisfying the combined scalar guard."),
            Thm("guarded_mixed_sound", "Unrestricted native soundness of extracted guards", "Take any actual finite branch B of the lowered original expressions, any named free-shape family s, a dependent decoration d of every actual shape leaf, and an assignment c of scalar atoms to collapse equations. If collect succeeds on every comparison extracted from B, then for every natural tuple n satisfying its returned affine guard and every arbitrary native tuple z, the original expressions are equal at the outputs rankedEval n z (assemble(s(inl x),d(inl x))). Scalar comparisons give equal primitive ranks. Matching residual blocks have identical shifts of the same encoded native parameter. Matching pairs reconstruct equal ambient codes. The three collapse comparisons provide their explicit natural rank. Existing arbitrary-code branch expansion then proves the original native equations. The hypotheses are finite syntactic comparison success and the extracted scalar equations, rather than a hypothesis asserting the desired original native equalities."),
            Def("scalarAddresses", "Enumerate explicit leaves of the actual free shape", "An explicit primitive contributes its empty address, a residual variable contributes none, and a pair prefixes false or true to its two lists of addresses. This enumeration traverses the total MGU term of every supported name."),
            Def("rankAt", "Read a rank at an actual code address", "Read the primitive rank at the specified subtree address, with zero as a total fallback. The extraction theorem proves that the fallback is excluded for every enumerated explicit MGU leaf."),
            Def("RankSlot", "Named scalar and collapse coordinates", "An explicit slot retains its name and ordered address. A collapse slot retains its output, left input and right input. Slots distinguish positions while repeated uses of a named value keep that same actual value."),
            Def("rankSlots", "Construct the finite scalar-coordinate list", "Traverse the presentation's entire name enumeration and every explicit leaf of its total MGU term, then append one slot for each occurrence of a collapse equation in the actual branch. Residual blocks contribute no scalar slot. Empty lists and zero scalar dimensions retain their ordinary meanings."),
            Def("RankSlot.value", "Read each coordinate from actual canonical codes", "An explicit slot reads its named subtree's primitive rank. A collapse slot reads the primitive rank of its right input, the same r shared by all three collapse equations."),
            Def("rankParameters", "Extract the natural tuple automatically", "Index rankSlots by its finite length and read RankSlot.value at each index from the same actual code assignment. This gives a finite tuple of natural numbers, with no supplied decorations or assumed successful comparison extraction."),
            Def("RankSlot.Correct", "Exact meaning of each extracted coordinate", "An explicit coordinate r means that the actual named subtree is the primitive code [r]. A collapse coordinate r means simultaneously that its actual left input is [r+1], its right input is [r], and its output is [r+2]."),
            Thm("finite_rank_extraction", "Actual-solution extraction on the finite total MGU", "For every finite original presentation E on the whole declared Fin d tuple and every actual solution v, first retain the identity finiteExtend E v (inputName E i) = v(i) at every original input, then select an actual branch of finiteEquations E and a successful total MGU of its shape equations. Every supported name factors through that MGU at the shape of its actual canonical code. The automatically constructed rankParameters tuple satisfies RankSlot.Correct at every index of rankSlots. Structural induction on the MGU term proves that each explicit leaf address lands at a primitive of the actual code. Reading that primitive recovers its rank. Actual branch soundness at each chosen collapse supplies all three equations with the rank read from its right input. The same construction includes all unused input names, repetitions, an empty declared tuple and branches with no scalar slots."),
            Def("slotScalar", "Use the actual finite scalar-coordinate index", "Look up an explicit or collapse slot in rankSlots and return its parameter with zero added offset. The total fallback is the constant zero, but membership at every actual explicit leaf and selected collapse excludes that fallback. Evaluation at rankParameters recovers the same actual slot value."),
            Def("residualOccurrences", "Keep the complete total-MGU occurrence list", "Reuse occurrenceVertices on every name in the actual finite presentation. The list retains each residual name, ordered address and residual sort, including occurrences in isolated unused input outputs."),
            Def("decorateAt", "Automatically decorate an actual shape subtree", "Recurse through the actual MGU subtree at a proved address. An explicit primitive receives slotScalar for that name and address. A residual receives its finite sort and natural offset from a map defined only at proved actual occurrences. Pairs recurse at the two appended child addresses. This dependent domain permits zero residual dimensions when no residual occurs."),
            Def("automaticDecoration", "Construct each full named decoration", "Apply decorateAt at the empty address of the actual total-MGU term of the named value. No scalar decoration is supplied as a premise."),
            Def("automaticCollapse", "Construct the shared collapse scalar", "Each selected collapse uses its actual collapse slot in the same finite scalar tuple. Its three branch comparisons therefore share one parameter, shifted by one, zero and two. Other branch constructors do not use this scalar."),
            Def("Pattern.frame", "Retain scalar versus residual syntax", "Erase scalar ranks and block labels, retaining different leaf tags for explicit scalars and residuals and preserving ordered pair constructors. An actual residual that happens to fill with a primitive is still a residual in this frame."),
            Def("blockCompatible", "The precise remaining residual comparison condition", "At two matching block leaves require the same finite sort and fixed natural offset. At matching pairs recurse on both children. Other combinations contribute no residual condition; successful MGU frame matching independently excludes mismatched constructors."),
            Def("Pattern.Agrees", "Read actual scalar leaves and pair constructors", "At a scalar leaf, the actual code must be the primitive with its evaluated rank. At a pair, the actual code must be the corresponding raw pair and both children must agree. A residual leaf contributes no assertion about its actual block. This predicate records scalar and constructor information and is not full code reconstruction."),
            Def("residualSorts", "Enumerate the finite actual residual sorts", "Map the complete occurrence list to its residual labels and deduplicate. This includes every isolated sort of an unused original name; no default sort is introduced for an empty list."),
            Def("residualSortIndex", "Index a proved actual residual sort", "The successful actual MGU supplies the exact occurrence-membership theorem. Use that membership to index the residual label in residualSorts. Thus the finite sort index is constructed from the actual MGU and needs no default element."),
            Def("sortedBlocks", "Combine automatic sorts with occurrence offsets", "Each proved residual occurrence receives its computed residualSortIndex and the supplied natural occurrence offset. Only these offsets remain external block data; scalar indices, collapse indices and finite residual sorts have already been constructed."),
            Thm("finite_guard_extraction", "Automatic source scalar guards with an exact residual obstruction", "For every original solution v on the entire Fin d tuple, retain every input identity and select an actual finite branch and successful total MGU. The returned witnesses include every actual branch equation and the same-assignment shape factorization at every supported name. For every assignment of natural offsets to its actual residual occurrences, use sortedBlocks and automaticDecoration to construct the named patterns and use automaticCollapse for their shared collapse scalars. At the rank tuple read from the same canonical codes, every named pattern agrees with its actual code in the precise scalar-and-pair sense above. Moreover there exists a successful collect result whose entire affine integer guard holds at those actual ranks if and only if blockCompatible holds throughout that same actual branchComparisons traversal. The proof derives comparison frames from the successful MGU equations. It derives scalar agreement from actual primitive constants, original fixed shifts, zero-offset ordinary pairs and equalities, and all three actual collapse equations. Recursive comparison then emits and verifies the scalar equalities. Neither successful collect nor scalar guard satisfaction is assumed. Residual offset compatibility is exposed as the exact remaining condition, rather than asserted to exist. The tuple, empty presentations and zero dimensions remain quantified."),
            Paragraph(Text("Concrete lowering, finite total-name reduction, automatic finite scalar and residual-sort decorations, the exact scalar-guard obstruction theorem and arbitrary-filling soundness hold on the original source objects. The independent signed-cycle/minimum-base supplier must still construct compatible nonnegative offsets on the actual sourceOffsetEdges, connect that edge law to blockCompatible in this traversal, and recover every actual residual block from its normal minimum block. Full actual-code reconstruction, lifting the finite-name templates to unrestricted original-expression soundness, construction of the finite chart list and both inclusions of the universal cover remain open. No corresponding supplier result or whole-cover conclusion is assumed here."))
        )));

    private static DocumentBlock Def(string name, string title, string text) =>
        name.Contains('.') ? Paragraph(Text(title + ". " + text)) :
            Entry(name, title, text, DescribeRole.Definition);
    private static DocumentBlock Thm(string name, string title, string text) =>
        Entry(name, title, text, DescribeRole.Theorem);
    private static DocumentBlock Entry(string name, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("mixed-native-" + name.Replace('.', '-').Replace('_', '-').ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(text))), role);
}
